import pandas as pd
import numpy as np


def run(inputs: dict) -> dict:
    dim_account = inputs['dim_account']
    stg_account = inputs['stg_account']

    # Build mutable in-memory state of current dimension rows
    state = []
    for _, row in dim_account.iterrows():
        state.append({
            'account_id': row['account_id'],
            'plan': row['plan'],
            'eff_start_date': row['eff_start_date'],
            'eff_end_date': row['eff_end_date'],
            'is_current': row['is_current'],
        })

    # Sort staging records by account_id, update_date (cursor order)
    stg_sorted = stg_account.sort_values(
        ['account_id', 'update_date'], kind='mergesort'
    )

    def plans_equal(p1, p2):
        n1 = pd.isna(p1)
        n2 = pd.isna(p2)
        if n1 and n2:
            return True
        if n1 != n2:
            return False
        return p1 == p2

    def covers(version, d):
        start = version['eff_start_date']
        end = version['eff_end_date']
        if pd.isna(start):
            start_ok = True
        else:
            start_ok = start <= d
        if pd.isna(end):
            end_ok = True
        else:
            end_ok = d < end
        return start_ok and end_ok

    for _, s in stg_sorted.iterrows():
        acc = s['account_id']
        plan = s['plan']
        d = s['update_date']

        acc_versions = [v for v in state if v['account_id'] == acc]

        if not acc_versions:
            state.append({
                'account_id': acc,
                'plan': plan,
                'eff_start_date': d,
                'eff_end_date': pd.NaT,
                'is_current': 1,
            })
            continue

        # find the version covering d
        v = None
        for ver in acc_versions:
            if covers(ver, d):
                v = ver
                break

        if v is None:
            # update_date earlier than the earliest existing version
            f = min(acc_versions, key=lambda x: x['eff_start_date'])
            state.append({
                'account_id': acc,
                'plan': plan,
                'eff_start_date': d,
                'eff_end_date': f['eff_start_date'],
                'is_current': 0,
            })
            continue

        if plans_equal(v['plan'], plan):
            # no-op
            continue

        if d == v['eff_start_date']:
            # same-day correction, no new version
            v['plan'] = plan
            continue

        # split the version at d
        new_row = {
            'account_id': acc,
            'plan': plan,
            'eff_start_date': d,
            'eff_end_date': v['eff_end_date'],
            'is_current': v['is_current'],
        }
        v['eff_end_date'] = d
        v['is_current'] = 0
        state.append(new_row)

    out = pd.DataFrame(
        state,
        columns=['account_id', 'plan', 'eff_start_date', 'eff_end_date', 'is_current']
    )

    if not out.empty:
        out['account_id'] = out['account_id'].astype(dim_account['account_id'].dtype)
        out['is_current'] = out['is_current'].astype(dim_account['is_current'].dtype)

    return {'dim_account_out': out}
